window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-616fb361807c8de9"]={"versions": [{"id": "FIG-616fb361807c8de9", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Systemkontexts und der architektonischen Schichtung der AUTOSAR Adaptive Platform (AP). Das Diagramm veranschaulicht die Einbettung der Plattform zwischen Anwendungssoftware (<code>Adaptive Application</code>) auf der Oberseite und Basisdiensten bzw. Hardware-/Treiberkomponenten (<code>Operating System</code>, <code>Watchdog</code>, <code>Crypto Provider</code>) auf der Unterseite sowie die vermittelnden Schnittstellenebenen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten (UML-Component):</li>\n<li><code>Adaptive Application</code>: Anwendungsebene oberhalb der Plattform.</li>\n<li><code>AUTOSAR Adaptive Platform</code>: Zentrales Paket/Subsystem (blau hinterlegt).</li>\n<li><code>Operating System</code>: Unterlagerte Betriebssystem-Komponente.</li>\n<li><code>Watchdog</code>: Hardware- bzw. externe Überwachungskomponente.</li>\n<li><code>Crypto Provider</code>: Kryptografische Dienstanbieter-Komponente.</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Schnittstellenblöcke (Rechtecke der Zwischenschicht) und Stereotype:</li>\n<li><code>«externalInterfac... Multi-Process System Interface</code></li>\n<li><code>«externalInterface» Single-Process POSIX API</code></li>\n<li><code>«externalInterfac... Non-volatile Storage</code></li>\n<li><code>«externalInterfac... TCP/IP Stack</code></li>\n<li><code>«externalInterface» Watchdog Driver</code></li>\n<li><code>«platformExtension... Crypto Provider</code> (Stereotyp oben «platformExtension...», oberhalb des Texts zudem «externalInterfac...»)</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Beziehungen:</li>\n<li>Gerichtete gestrichelte Pfeile («use»):</li>\n<li>Von <code>Adaptive Application</code> auf <code>AUTOSAR Adaptive Platform</code>.</li>\n<li>Von <code>AUTOSAR Adaptive Platform</code> auf alle sechs Schnittstellenblöcke der Zwischenebene.</li>\n<li>Realisierungs-/Generalisierungsbeziehungen (gestrichelte Linien mit geschlossener, nicht ausgefüllter Dreiecksspitze):</li>\n<li>Von <code>Operating System</code> zu den vier Schnittstellen <code>Multi-Process System Interface</code>, <code>Single-Process POSIX API</code>, <code>Non-volatile Storage</code> und <code>TCP/IP Stack</code>.</li>\n<li>Von <code>Watchdog</code> zur Schnittstelle <code>Watchdog Driver</code>.</li>\n<li>Von <code>Crypto Provider</code> zur Schnittstelle <code>Crypto Provider</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichten- und Nutzungsbeziehung ohne zeitlichen Sequenzablauf: Aufrufe erfolgen top-down von den adaptiven Applikationen an die AUTOSAR Adaptive Platform über «use»-Abhängigkeiten. Die Plattform greift ihrerseits über die definierten externen Schnittstellen und Plattform-Erweiterungen («use») auf die vom Betriebssystem, dem Watchdog und dem Crypto-Provider realisierten Dienste zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturrichtlinie für Schnittstellenkategorien im Systemkontext: Adaptive Applikationen greifen ausschließlich auf die Adaptive Platform zu. Das Fundament der Plattform gliedert sich normativ in vom Betriebssystem bereitgestellte Schnittstellen (POSIX- und Multi-Process-Schnittstellen, NVM, TCP/IP) sowie spezifische Treiber/Erweiterungen für Watchdog und Kryptografie (<code>Crypto Provider</code>), die über externe Schnittstellen (<code>«externalInterface»</code>) und Plattform-Erweiterungen (<code>«platformExtension»</code>) angebunden werden müssen.</p>"}, {"id": "FIG-7b8a67ac027b5fa6", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Systemkontexts und der architektonischen Schichtung der AUTOSAR Adaptive Platform (AP). Das Diagramm veranschaulicht die Einbettung der Plattform zwischen Anwendungssoftware (<code>Adaptive Application</code>) auf der Oberseite und Basisdiensten bzw. Hardware-/Treiberkomponenten (<code>Operating System</code>, <code>Watchdog</code>, <code>Crypto Provider</code>) auf der Unterseite sowie die vermittelnden Schnittstellenebenen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten (UML-Component):</li>\n<li><code>Adaptive Application</code>: Oberste Anwendungskomponente.</li>\n<li><code>AUTOSAR Adaptive Platform</code>: Zentrales Subsystem (blau hinterlegt).</li>\n<li><code>Operating System</code>: Unterlagerte Betriebssystem-Komponente.</li>\n<li><code>Watchdog</code>: Externe Überwachungseinheit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Schnittstellenblöcke der Zwischenebene:</li>\n<li><code>«aapInternal» Multi-Process System Interface</code></li>\n<li><code>«aapInternal» Single-Process POSIX API</code></li>\n<li><code>«aapInternal» Non-volatile Storage</code></li>\n<li><code>«aapInternal» TCP/IP Stack</code></li>\n<li><code>«aapNativeInterf... Platform Health Management::WatchdogInterface</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li>Beziehungen:</li>\n<li>Gerichtete «use»-Abhängigkeiten:</li>\n<li>Von <code>Adaptive Application</code> auf <code>AUTOSAR Adaptive Platform</code>.</li>\n<li>Von <code>AUTOSAR Adaptive Platform</code> auf die fünf Schnittstellenblöcke der Zwischenebene.</li>\n<li>Realisierungsbeziehungen (gestrichelte Linien mit hohler Dreiecksspitze):</li>\n<li>Von <code>Operating System</code> zu den vier internen Schnittstellen (<code>Multi-Process System Interface</code>, <code>Single-Process POSIX API</code>, <code>Non-volatile Storage</code>, <code>TCP/IP Stack</code>).</li>\n<li>Von <code>Watchdog</code> zu <code>Platform Health Management::WatchdogInterface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architektur- und Nutzungsstruktur: Der Kontroll- und Nutzungsfluss verläuft abwärts von der <code>Adaptive Application</code> über «use» auf die <code>AUTOSAR Adaptive Platform</code>. Die Plattform interagiert über vier plattforminterne Schnittstellen (<code>«aapInternal»</code>) mit dem Betriebssystem sowie über eine native Plattform-Schnittstelle (<code>«aapNativeInterf...</code>) des Platform Health Management mit dem Watchdog.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Klassifikation der Schnittstellen nach AUTOSAR Adaptive Platform Architekturkonzepten: Unterlagerte Betriebssystem-Dienste (POSIX, Multi-Process, NVM, Netzwerk/TCP) sind als plattformintern (<code>«aapInternal»</code>) klassifiziert. Die Watchdog-Interaktion erfolgt formalisiert über das funktionale Cluster Platform Health Management mittels <code>Platform Health Management::WatchdogInterface</code> als native Adaptive-Platform-Schnittstelle (<code>«aapNativeInterf...</code>). Ein separater externer Crypto-Provider-Block ist in dieser Systemkontextübersicht nicht mehr als Schnittstellen- und Komponenteninstanz ausgewiesen.</p>"}, {"id": "FIG-4da832302bf88d30", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Systemkontexts und der architektonischen Schichtung der AUTOSAR Adaptive Platform (AP). Das Diagramm veranschaulicht die Einbettung der Plattform zwischen Anwendungssoftware (<code>Adaptive Application</code>) auf der Oberseite und Basisdiensten bzw. Hardware-/Treiberkomponenten (<code>Operating System</code>, <code>Watchdog</code>, <code>Crypto Provider</code>) auf der Unterseite sowie die vermittelnden Schnittstellenebenen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten (UML-Component):</li>\n<li><code>Adaptive Application</code>: Oberste Anwendungskomponente.</li>\n<li><code>AUTOSAR Adaptive Platform</code>: Zentrales Subsystem (blau hinterlegt).</li>\n<li><code>Operating System</code>: Unterlagerte Betriebssystem-Komponente.</li>\n<li><code>Watchdog</code>: Externe Überwachungseinheit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Schnittstellenblöcke der Zwischenebene:</li>\n<li><code>«aapInternal» Multi-Process System Interface</code></li>\n<li><code>«aapInternal» Single-Process POSIX API</code></li>\n<li><code>«aapInternal» Non-volatile Storage</code></li>\n<li><code>«aapInternal» TCP/IP Stack</code></li>\n<li><code>«aapNativeInterf... Platform Health Management::WatchdogInterface</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li>Beziehungen:</li>\n<li>Gerichtete «use»-Abhängigkeiten:</li>\n<li>Von <code>Adaptive Application</code> auf <code>AUTOSAR Adaptive Platform</code>.</li>\n<li>Von <code>AUTOSAR Adaptive Platform</code> auf die fünf Schnittstellenblöcke der Zwischenebene.</li>\n<li>Realisierungsbeziehungen (gestrichelte Linien mit hohler Dreiecksspitze):</li>\n<li>Von <code>Operating System</code> zu den vier internen Schnittstellen (<code>Multi-Process System Interface</code>, <code>Single-Process POSIX API</code>, <code>Non-volatile Storage</code>, <code>TCP/IP Stack</code>).</li>\n<li>Von <code>Watchdog</code> zu <code>Platform Health Management::WatchdogInterface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architektur- und Nutzungsstruktur: Der Kontroll- und Nutzungsfluss verläuft abwärts von der <code>Adaptive Application</code> über «use» auf die <code>AUTOSAR Adaptive Platform</code>. Die Plattform interagiert über vier plattforminterne Schnittstellen (<code>«aapInternal»</code>) mit dem Betriebssystem sowie über eine native Plattform-Schnittstelle (<code>«aapNativeInterf...</code>) des Platform Health Management mit dem Watchdog.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Klassifikation der Schnittstellen nach AUTOSAR Adaptive Platform Architekturkonzepten: Unterlagerte Betriebssystem-Dienste (POSIX, Multi-Process, NVM, Netzwerk/TCP) sind als plattformintern (<code>«aapInternal»</code>) klassifiziert. Die Watchdog-Interaktion erfolgt formalisiert über das funktionale Cluster Platform Health Management mittels <code>Platform Health Management::WatchdogInterface</code> als native Adaptive-Platform-Schnittstelle (<code>«aapNativeInterf...</code>). Ein separater externer Crypto-Provider-Block ist in dieser Systemkontextübersicht nicht mehr als Schnittstellen- und Komponenteninstanz ausgewiesen.</p>"}, {"id": "FIG-44223525e4ac21fc", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm zur Darstellung des Systemkontexts und der architektonischen Schichtung der AUTOSAR Adaptive Platform (AP). Das Diagramm veranschaulicht die Einbettung der Plattform zwischen Anwendungssoftware (<code>Adaptive Application</code>) auf der Oberseite und Basisdiensten bzw. Hardware-/Treiberkomponenten (<code>Operating System</code>, <code>Watchdog</code>, <code>Crypto Provider</code>) auf der Unterseite sowie die vermittelnden Schnittstellenebenen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Komponenten (UML-Component):</li>\n<li><code>Adaptive Application</code>: Oberste Anwendungskomponente.</li>\n<li><code>AUTOSAR Adaptive Platform</code>: Zentrales Subsystem (blau hinterlegt).</li>\n<li><code>Operating System</code>: Unterlagerte Betriebssystem-Komponente.</li>\n<li><code>Watchdog</code>: Externe Überwachungseinheit.</li>\n</ul>\n<ul class=\"fig-list\">\n<li>Schnittstellenblöcke der Zwischenebene:</li>\n<li><code>«aapInternal» Multi-Process System Interface</code></li>\n<li><code>«aapInternal» Single-Process POSIX API</code></li>\n<li><code>«aapInternal» Non-volatile Storage</code></li>\n<li><code>«aapInternal» TCP/IP Stack</code></li>\n<li><code>«aapNativeInterf... Platform Health Management::WatchdogInterface</code></li>\n</ul>\n<ul class=\"fig-list\">\n<li>Beziehungen:</li>\n<li>Gerichtete «use»-Abhängigkeiten:</li>\n<li>Von <code>Adaptive Application</code> auf <code>AUTOSAR Adaptive Platform</code>.</li>\n<li>Von <code>AUTOSAR Adaptive Platform</code> auf die fünf Schnittstellenblöcke der Zwischenebene.</li>\n<li>Realisierungsbeziehungen (gestrichelte Linien mit hohler Dreiecksspitze):</li>\n<li>Von <code>Operating System</code> zu den vier internen Schnittstellen (<code>Multi-Process System Interface</code>, <code>Single-Process POSIX API</code>, <code>Non-volatile Storage</code>, <code>TCP/IP Stack</code>).</li>\n<li>Von <code>Watchdog</code> zu <code>Platform Health Management::WatchdogInterface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Architektur- und Nutzungsstruktur: Der Kontroll- und Nutzungsfluss verläuft abwärts von der <code>Adaptive Application</code> über «use» auf die <code>AUTOSAR Adaptive Platform</code>. Die Plattform interagiert über vier plattforminterne Schnittstellen (<code>«aapInternal»</code>) mit dem Betriebssystem sowie über eine native Plattform-Schnittstelle (<code>«aapNativeInterf...</code>) des Platform Health Management mit dem Watchdog.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Klassifikation der Schnittstellen nach AUTOSAR Adaptive Platform Architekturkonzepten: Unterlagerte Betriebssystem-Dienste (POSIX, Multi-Process, NVM, Netzwerk/TCP) sind als plattformintern (<code>«aapInternal»</code>) klassifiziert. Die Watchdog-Interaktion erfolgt formalisiert über das funktionale Cluster Platform Health Management mittels <code>Platform Health Management::WatchdogInterface</code> als native Adaptive-Platform-Schnittstelle (<code>«aapNativeInterf...</code>). Ein separater externer Crypto-Provider-Block ist in dieser Systemkontextübersicht nicht mehr als Schnittstellen- und Komponenteninstanz ausgewiesen.</p>"}], "trans": [{"from": "FIG-616fb361807c8de9", "to": "FIG-7b8a67ac027b5fa6", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Stereotyp der Schnittstellen zur Plattformunterlagerung geändert: «externalInterface» bzw. «externalInterfac...» durch «aapInternal» ersetzt (betrifft <code>Multi-Process System Interface</code>, <code>Single-Process POSIX API</code>, <code>Non-volatile Storage</code>, <code>TCP/IP Stack</code>).</li>\n<li>Schnittstelle und Komponente <code>Crypto Provider</code> (mit Stereotyp «platformExtension...» bzw. «externalInterfac...») ersatzlos entfernt.</li>\n<li>Schnittstelle <code>Watchdog Driver</code> («externalInterface») ersetzt durch <code>Platform Health Management::WatchdogInterface</code> mit dem Stereotyp «aapNativeInterf...».</li>\n<li>Zugehörige «use»-Abhängigkeiten von <code>AUTOSAR Adaptive Platform</code> auf fünf Schnittstellenblöcke reduziert (vormals sechs).</li>\n</ul>"}, {"from": "FIG-7b8a67ac027b5fa6", "to": "FIG-4da832302bf88d30", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4da832302bf88d30", "to": "FIG-44223525e4ac21fc", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bildbeschnitt am oberen Rand geändert (abgeschnittene Textfragmente einer darüberliegenden Textzeile des Dokuments im oberen Bildbereich sichtbar).</li>\n</ul>"}]};
